  support::BytesInStream stream(bytes);
  std::string data;
  ffi::Map<ffi::String, FunctionInfo> fmap;
  std::string fmt;
  stream.Read(&fmt);
  TVM_FFI_ICHECK(stream.Read(&fmap));
  stream.Read(&data);
  return MACAModuleCreate(data, fmt, fmap, std::string());
}

